{
  "name": "@bangbang93/opencode-edit-error-recovery",
  "version": "0.1.0",
  "description": "OpenCode plugin that tells the model to read the file again after its edit failed",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "edit-error-recovery"
  ],
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "NOTICE.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.4.2"
  },
  "scripts": {
    "test": "node --test index.test.ts",
    "test:bun": "bun test",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  }
}

import { Plugin } from "@opencode/plugin"

// Parts of the edit tool's error messages that mean the model's idea of the file was wrong.
const MISMATCH = ["No changes to apply:", "Could not find oldString in", "matches for oldString, but expected exactly one"]

const REMINDER = `[edit-error-recovery]
This edit failed because something you assumed about the file is wrong. Before the next attempt:
1. Read the file to see what it contains now.
2. Compare the real content with your oldString and newString, and find where your assumption was wrong.
3. Apologize to the user in one sentence for the failed edit.
4. Continue with an edit built from the real content.
Do not call edit again until you have read the file.`

export default Plugin.define({
  id: "edit-error-recovery",
  async setup(ctx) {
    await ctx.tool.hook("execute.after", (event) => {
      if (event.status !== "error" || event.tool !== "edit") return
      if (!MISMATCH.some((part) => event.error.message.includes(part))) return
      Object.assign(event.error, { message: `${event.error.message}\n\n${REMINDER}` })
    })
  },
})
